const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2020-01-01';
    const end = '2020-02-01';
    const city = ee.Geometry.Point([46.3167, -15.7167]).buffer({distance: 10000}); // Mahajanga ~10 km radius
    const scale = 5500; // ~0.05 deg

    // Helper to await server-side results
    const getInfoAsync = (eeObj) =>
      new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));

    // 2. Data Acquisition & Check with fallbacks
    let img = null;
    let sourceUsed = null;

    const colMonthly = ee.ImageCollection('UCSB-CHG/CHIRPS/Monthly')
      .filterDate(start, end)
      .filterBounds(city)
      .select('precipitation');
    const mSize = await getInfoAsync(colMonthly.size());
    console.log(`CHIRPS Monthly Images: ${mSize}`);
    if (mSize > 0) {
      img = colMonthly.sum().rename('precipitation').clip(city);
      sourceUsed = 'CHIRPS Monthly';
    } else {
      const colDaily = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(start, end)
        .filterBounds(city)
        .select('precipitation')
        .map(function(i){ return i.clip(city); });
      const dSize = await getInfoAsync(colDaily.size());
      console.log(`CHIRPS Daily Images: ${dSize}`);
      if (dSize > 0) {
        img = colDaily.sum().rename('precipitation').clip(city);
        sourceUsed = 'CHIRPS Daily (summed)';
      } else {
        const colEra = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY')
          .filterDate(start, end)
          .filterBounds(city)
          .select('total_precipitation');
        const eSize = await getInfoAsync(colEra.size());
        console.log(`ERA5-Land Monthly Images: ${eSize}`);
        if (eSize > 0) {
          // Convert meters to mm
          img = colEra.sum().multiply(1000).rename('precipitation').clip(city);
          sourceUsed = 'ERA5-Land Monthly (mm)';
        } else {
          console.log('No images found across sources for Jan 2020 in AOI.');
          console.log('C1');
          return;
        }
      }
    }

    // 3. Processing & Valid Pixel Check
    const countDict = await getInfoAsync(
      img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: city,
        scale: scale,
        maxPixels: 1e9
      })
    );
    const pxCount = (countDict && countDict.precipitation) ? countDict.precipitation : 0;
    console.log(`Source Used: ${sourceUsed}`);
    console.log(`Valid Pixels: ${pxCount}`);
    if (!pxCount || pxCount === 0) {
      console.log('C2');
      return;
    }

    // 4. Calculation
    const meanDict = await getInfoAsync(
      img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: city,
        scale: scale,
        maxPixels: 1e9
      })
    );
    const mm = meanDict ? meanDict.precipitation : null;

    // 5. Validation & Final Answer
    if (mm === null || mm === undefined || isNaN(mm) || mm < 0 || mm > 10000) {
      console.log(`Precip (mm): ${mm}`);
      console.log('C3');
      return;
    }
    const inches = mm / 25.4;
    console.log(`Jan 2020 Precip: ${mm.toFixed(1)} mm (${inches.toFixed(2)} in)`);

    // Threshold: 12 inches = 304.8 mm
    if (inches > 12.0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
